const body = $input.first().json.body || $input.first().json;

const url = body.url || '';
const userNote = body.note || body.text || '';
const sharedTitle = body.title || '';

let platform = 'web';
if (/youtu\.?be/i.test(url)) platform = 'youtube';
else if (/instagram\.com/i.test(url)) platform = 'instagram';
else if (/tiktok\.com/i.test(url)) platform = 'tiktok';
else if (/twitter\.com|x\.com/i.test(url)) platform = 'twitter';
else if (/linkedin\.com/i.test(url)) platform = 'linkedin';

const now = new Date();
const iso = now.toISOString();
const date = iso.split('T')[0];
const time = iso.split('T')[1].substring(0, 5);

const prompt = `Clasifica este insight capturado desde móvil para el Research Power Stack de Diego (ZENTI + Charly.io).\n\n**URL:** ${url}\n**Plataforma:** ${platform}\n**Título compartido:** ${sharedTitle}\n**Nota del usuario:** ${userNote}\n\nDevuelve SOLO JSON válido (sin markdown, sin \\\`\\\`\\\`json):\n{\n  "title": "título conciso 5-8 palabras",\n  "category": "ai-tech | fundraising | product | growth | sales | ops | leadership | otro",\n  "relevance": {\n    "zenti": 0-10,\n    "charly": 0-10\n  },\n  "summary": "2-3 frases sobre la idea central",\n  "keyPoints": ["punto 1", "punto 2", "punto 3"],\n  "actionable": "acción concreta en 1 frase, o 'solo-referencia' si no aplica",\n  "tags": ["#tag1", "#tag2", "#tag3"],\n  "priority": "alta | media | baja"\n}\n\nContexto de proyectos:\n- **ZENTI**: sistema multi-agente AI para evaluar propuestas CORFO/ANID/BID. Stack: n8n + Claude + RAG pgvector.\n- **Charly.io**: SaaS B2B para gestión de programas de aceleración en LATAM.`;

return [{
  json: {
    url,
    userNote,
    sharedTitle,
    platform,
    capturedAt: iso,
    date,
    time,
    prompt
  }
}];

const input = $('Parse Input').first().json;
const resp = $input.first().json;
const raw = resp?.content?.[0]?.text || '';

let parsed;
try {
  const cleaned = raw.replace(/^```json\s*|```\s*$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    title: input.sharedTitle || 'Insight sin título',
    category: 'otro',
    relevance: { zenti: 0, charly: 0 },
    summary: input.userNote || 'No se pudo clasificar',
    keyPoints: [],
    actionable: 'solo-referencia',
    tags: ['#sin-clasificar'],
    priority: 'baja'
  };
}

const slug = parsed.title.toLowerCase()
  .replace(/[^a-z0-9áéíóúñ\s-]/g, '')
  .replace(/\s+/g, '-')
  .substring(0, 50);

const filename = `${input.date}-${slug}.md`;
const filepath = `INSIGHTS/${parsed.category}/${filename}`;

const inboxEntry = `
### ${parsed.title}
- **Hora:** ${input.time}
- **Fuente:** [${input.platform}](${input.url})
- **Categoría:** ${parsed.category} | **Prioridad:** ${parsed.priority}
- **Relevancia:** ZENTI ${parsed.relevance.zenti}/10 · Charly ${parsed.relevance.charly}/10
- **Resumen:** ${parsed.summary}
- **Acción:** ${parsed.actionable}
- **Tags:** ${parsed.tags.join(' ')}
- [[${filepath}|Ver detalle]]
`;

const insightMd = `---
title: "${parsed.title}"
date: ${input.date}
time: ${input.time}
source: ${input.url}
platform: ${input.platform}
category: ${parsed.category}
priority: ${parsed.priority}
relevance_zenti: ${parsed.relevance.zenti}
relevance_charly: ${parsed.relevance.charly}
tags: [${parsed.tags.map(t => `"${t.replace('#','')}"`).join(', ')}]
---

# ${parsed.title}

> **Fuente:** [${input.platform}](${input.url})  
> **Capturado:** ${input.date} ${input.time}

## Resumen
${parsed.summary}

## Puntos Clave
${parsed.keyPoints.map(p => `- ${p}`).join('
')}

## Acción Propuesta
${parsed.actionable}

## Nota Original
${input.userNote || '_sin nota adicional_'}

## Conexiones
- Relevancia ZENTI: ${parsed.relevance.zenti}/10
- Relevancia Charly.io: ${parsed.relevance.charly}/10
- Categoría: #${parsed.category}

${parsed.tags.join(' ')}
`;

return [{
  json: {
    status: 'ok',
    title: parsed.title,
    category: parsed.category,
    priority: parsed.priority,
    zentiRelevance: parsed.relevance.zenti,
    charlyRelevance: parsed.relevance.charly,
    filename,
    filepath,
    inboxEntry,
    insightMd
  }
}];
